/// Earth: ground surface made with noise (above the ground = air)
/// ---- Settings (to share with other maps, delete the line and add the same name to Variables) ----
int airId = 1;        // air id
int earthId = 3;      // earth id
int earthLevel = 0;   // ground height (cells from the top)
int earthRange = 10;  // height of the hills
float scale = 0.1;    // noise scale (smaller = smoother)

for (int y = 0; y < height; y++) { for (int x = 0; x < width; x++) {
	int n = noise(x, y, scale) * earthRange;
	if (y > n + earthLevel) { result[y][x] = earthId; } else { result[y][x] = airId; }
} }
